descriptor.controllerScript:
self.onInit = function () {
  const s = self.ctx.$scope;

  // Initialize scope variables with defaults
  s.device_name = 'Unknown Device';
  s.profile_name = 'Default Profile';
  s.device_image_url = 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSyiJYLDHwbasZWbpisyZhplDLs9vcc62tlnA&s';

  s.serial = 'N/A';
  s.mac = 'N/A';
  s.imei = 'N/A';
  s.firmware = 'N/A';
  s.iccid = 'N/A';
  s.sim_status = 'N/A';

  s.mobile_status = 'N/A';
  s.usb0_ip = '0.0.0.0';
  s.provider = 'N/A';
  s.operator = 'N/A';

  s.is_online = false;

  s.uptime_raw = 0;
  s.uptime_formatted = '0h 0m';
  s.cpu_usage = '0.00'; // As percent
  s.ram_used = 0;
  s.ram_total = 256; // MB
  s.ram_percent = 0;
  s.flash_used = 0;
  s.flash_total = 64; // MB
  s.flash_percent = 0;
  s.device_temperature = 0;

  // Inject Tailwind if not already present
  if (!document.getElementById('tailwindcss')) {
    window.tailwind = {
      config: {
        safelist: [
          'grid','grid-cols-1','md:grid-cols-4','gap-6','text-sm','font-semibold','rounded','bg-gray-200',
          'transition-all','duration-300','ease-out','text-gray-500','text-red-600','text-green-500',
          'p-4','mt-1','font-mono','flex','items-center','justify-between','object-contain','border',
          'hover:bg-blue-600','px-3','py-1'
        ],
        corePlugins: { preflight: false }
      }
    };
    const script = document.createElement('script');
    script.src = 'https://cdn.tailwindcss.com';
    script.id = 'tailwindcss';
    script.onload = () => setTimeout(() => self.ctx.detectChanges(), 50);
    document.head.appendChild(script);
  } else {
    setTimeout(() => self.ctx.detectChanges(), 50);
  }
};

self.onDataUpdated = function () {
  const s = self.ctx.$scope;
  const data = self.ctx.data;

  // Helper: returns the latest value for a given key, or null if not found
  const getValue = (key) => {
    const entry = data.find(d => d.dataKey.name === key);
    return entry && entry.data && entry.data.length
      ? entry.data[entry.data.length - 1][1]
      : null;
  };

  // If a key is missing, we use random fallback to produce realistic data
  // You can adjust these fallback ranges as needed.

  // 1) Device Basic Info
  s.device_name = getValue('device_name') || 'RUT200';
  s.profile_name = getValue('profile_name') || 'Default Profile';
  s.device_image_url = getValue('device_image_url') ||
    'https://static01.galaxus.com/productimages/3/7/1/5/0/6/6/3/3/4/2/0/4/1/8/6/5/8/3/3069e726-12ee-45d3-a981-24230163236b.jpg_480.avif';
  s.is_online = getValue('is_online');
  if (s.is_online === null) {
    // random boolean
    s.is_online = Math.random() < 0.7;
  }

  // 2) Column 2 Data
  s.serial = getValue('serial') || '6001776129';
  s.mac = getValue('mac') || '30:07:23:EF:54:B8';
  s.imei = getValue('imei') || '869533056449614';
  s.firmware = getValue('firmware') || 'RUT2_R_00.07.03.2';
  s.iccid = getValue('iccid') || 'N/A';
  s.sim_status = getValue('sim_status') || 'Active';

  // 3) Column 3 Data
  s.mobile_status = getValue('mobile_status') || 'Active';
  s.usb0_ip = getValue('usb0_ip') || '10.254.13.62';
  s.provider = getValue('provider') || 'N/A';
  s.operator = getValue('operator') || 'N/A';

  // 4) Column 4 Data

  // Uptime (raw seconds -> d/h/m/s)
  let rawUptime = parseFloat(getValue('uptime'));
  if (isNaN(rawUptime)) {
    // fallback: random up to 3 days
    rawUptime = Math.floor(Math.random() * 259200); // 3 days in seconds
  }
  s.uptime_raw = rawUptime;
  s.uptime_formatted = formatUptime(rawUptime);

  // CPU usage
  let cpuRaw = parseFloat(getValue('cpu_usage'));
  if (isNaN(cpuRaw)) {
    // fallback: random fraction [0, 1]
    cpuRaw = Math.random();
  }
  s.cpu_usage = (cpuRaw * 100).toFixed(2);

  // RAM
  let ramTotal = parseFloat(getValue('ram_total'));
  if (isNaN(ramTotal)) {
    ramTotal = 128 + Math.floor(Math.random() * 256); // random total 128..384
  }
  s.ram_total = ramTotal;

  let ramUsed = parseFloat(getValue('ram_used'));
  if (isNaN(ramUsed)) {
    // fallback: random usage up to ramTotal
    ramUsed = Math.floor(Math.random() * ramTotal);
  }
  s.ram_used = ramUsed;
  s.ram_percent = ((ramUsed / ramTotal) * 100).toFixed(2);

  // Flash
  let flashTotal = parseFloat(getValue('flash_total'));
  if (isNaN(flashTotal)) {
    flashTotal = 4; // default 4MB for smaller device, or whatever is typical
  }
  s.flash_total = flashTotal;

  let flashUsed = parseFloat(getValue('flash_used'));
  if (isNaN(flashUsed)) {
    // fallback: random usage up to flashTotal
    flashUsed = (Math.random() * flashTotal).toFixed(2);
  }
  s.flash_used = flashUsed;
  s.flash_percent = ((flashUsed / flashTotal) * 100).toFixed(2);

  // Temperature
  let tempRaw = parseFloat(getValue('device_temperature'));
  if (isNaN(tempRaw)) {
    // fallback: random 20..80
    tempRaw = (20 + Math.random() * 60).toFixed(2);
  }
  s.device_temperature = parseFloat(tempRaw);

  self.ctx.detectChanges();

  // Helper function to format uptime in d/h/m/s
  function formatUptime(seconds) {
    const d = Math.floor(seconds / 86400);
    seconds %= 86400;
    const h = Math.floor(seconds / 3600);
    seconds %= 3600;
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;

    // Example format: "1d 3h 42m 10s"
    let parts = [];
    if (d > 0) parts.push(d + 'd');
    if (h > 0) parts.push(h + 'h');
    if (m > 0) parts.push(m + 'm');
    parts.push(s + 's');
    return parts.join(' ');
  }
};

self.onDestroy = function () {
  console.log('Widget destroyed');
};

